/**
 * Optional PWA support: registers the service worker generated by vite-plugin-pwa so the app shell
 * is cached and works offline, and exposes the browser's "install" prompt.
 * Nothing here ever touches document content.
 */
import { useSyncExternalStore } from 'react';

let state = { justReady: false, offlineReady: false, updateReady: false, canInstall: false, installed: false, supported: 'serviceWorker' in navigator };
const listeners = new Set();
let deferredPrompt = null;

function set(patch) {
  state = { ...state, ...patch };
  listeners.forEach((l) => l());
}

export function usePwaState() {
  return useSyncExternalStore(
    (fn) => {
      listeners.add(fn);
      return () => listeners.delete(fn);
    },
    () => state,
    () => state,
  );
}

export async function promptInstall() {
  if (!deferredPrompt) return false;
  deferredPrompt.prompt();
  const { outcome } = await deferredPrompt.userChoice;
  deferredPrompt = null;
  set({ canInstall: false, installed: outcome === 'accepted' });
  return outcome === 'accepted';
}

export async function initPwa() {
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPrompt = e;
    set({ canInstall: true });
  });
  window.addEventListener('appinstalled', () => set({ installed: true, canInstall: false }));

  // The service worker only exists in production builds.
  if (!import.meta.env.PROD || !('serviceWorker' in navigator)) return;
  try {
    const { registerSW } = await import('virtual:pwa-register');
    registerSW({
      immediate: true,
      onOfflineReady: () => set({ offlineReady: true, justReady: true }),
      onNeedRefresh: () => set({ updateReady: true }),
      onRegisterError: () => set({ supported: false }),
    });
    // If a worker already controls the page, we were cached on an earlier visit.
    if (navigator.serviceWorker.controller) set({ offlineReady: true });
  } catch {
    set({ supported: false });
  }
}
